import { css } from '@emotion/css';
import { useCallback, useMemo, useRef, type ChangeEvent, type MouseEvent } from 'react';

import { colorManipulator, type GrafanaTheme2, type LogRowModel, store } from '@grafana/data';
import { t } from '@grafana/i18n';
import { reportInteraction } from '@grafana/runtime';
import { Dropdown, IconButton, Input, Menu, useStyles2 } from '@grafana/ui';

import { copyText, handleOpenLogsContextClick } from '../../utils';
import { LOG_LINE_BODY_FIELD_NAME } from '../fieldSelector/logFields';

import { useLogDetailsContext } from './LogDetailsContext';
import { type LogLineDetailsMode } from './LogLineDetails';
import { useLogIsPinned, useLogListContext } from './LogListContext';
import { getLogAsJSON } from './export';
import { type LogListModel } from './processing';

interface Props {
  closeDetails: () => void;
  detailsMode: LogLineDetailsMode;
  focusLogLine?: (log: LogListModel) => void;
  inlineNoScroll?: boolean;
  log: LogListModel;
  search: string;
  setInlineNoScroll?(inlineNoScroll: boolean): void;
  setDetailsMode?(mode: LogLineDetailsMode): void;
  onSearch(newSearch: string): void;
}

export const LogLineDetailsHeader = ({
  closeDetails,
  detailsMode,
  focusLogLine,
  inlineNoScroll,
  log,
  search,
  setDetailsMode,
  setInlineNoScroll,
  onSearch,
}: Props) => {
  const {
    displayedFields,
    getRowContextQuery,
    logOptionsStorageKey,
    logSupportsContext,
    noInteractions,
    onClickHideField,
    onClickShowField,
    onOpenContext,
    onPermalinkClick,
    onPinLine,
    onUnpinLine,
    wrapLogMessage,
    isAssistantAvailable,
    openAssistantByLog,
  } = useLogListContext();
  const { toggleDetails } = useLogDetailsContext();
  const pinned = useLogIsPinned(log);
  const styles = useStyles2(getStyles, detailsMode, wrapLogMessage);
  const containerRef = useRef<HTMLDivElement | null>(null);
  const inputRef = useRef<HTMLInputElement | null>(null);
  const searchUsedRef = useRef(false);

  const reportInteractionWrapper = useCallback(
    (interactionName: string, properties?: Record<string, unknown>) => {
      if (noInteractions) {
        return;
      }
      reportInteraction(interactionName, properties);
    },
    [noInteractions]
  );

  const scrollToLogLine = useCallback(() => {
    focusLogLine?.(log);
    reportInteractionWrapper('logs_log_line_details_header_scroll_to_clicked');
  }, [focusLogLine, log, reportInteractionWrapper]);

  const copyLogLine = useCallback(() => {
    copyText(log.entry, containerRef);
    reportInteractionWrapper('logs_log_line_details_header_copy_clicked');
  }, [log.entry, reportInteractionWrapper]);

  const copyLogLineAsJson = useCallback(async () => {
    copyText(await getLogAsJSON(log), containerRef);
    reportInteractionWrapper('logs_log_line_details_header_copy_json_clicked');
  }, [log, reportInteractionWrapper]);

  const copyLinkToLogLine = useCallback(() => {
    onPermalinkClick?.(log);
    reportInteractionWrapper('logs_log_line_details_header_permalink_clicked');
  }, [log, onPermalinkClick, reportInteractionWrapper]);

  const togglePinning = useCallback(() => {
    if (pinned) {
      onUnpinLine?.(log);
    } else {
      onPinLine?.(log);
    }
    reportInteractionWrapper('logs_log_line_details_header_pinning_clicked');
  }, [log, onPinLine, onUnpinLine, pinned, reportInteractionWrapper]);

  const shouldlogSupportsContext = useMemo(
    () => (logSupportsContext ? logSupportsContext(log) : false),
    [log, logSupportsContext]
  );

  const showContext = useCallback(
    async (event: MouseEvent<HTMLElement>) => {
      handleOpenLogsContextClick(event, log, getRowContextQuery, (log: LogRowModel) => onOpenContext?.(log, () => {}));
      reportInteractionWrapper('logs_log_line_details_header_context_clicked');
    },
    [log, getRowContextQuery, reportInteractionWrapper, onOpenContext]
  );

  const showLogLineToggle = onClickHideField && onClickShowField && displayedFields.length > 0;
  const logLineDisplayed = displayedFields.includes(LOG_LINE_BODY_FIELD_NAME);

  const toggleDetailsMode = useCallback(() => {
    const newMode = detailsMode === 'inline' ? 'sidebar' : 'inline';
    if (logOptionsStorageKey) {
      store.set(`${logOptionsStorageKey}.detailsMode`, newMode);
    }

    setDetailsMode?.(newMode);

    reportInteractionWrapper('logs_log_line_details_header_toggle_details_mode', {
      newMode,
    });
  }, [detailsMode, logOptionsStorageKey, reportInteractionWrapper, setDetailsMode]);

  const toggleDetailsScroll = useCallback(() => {
    const newState = !inlineNoScroll;
    if (logOptionsStorageKey) {
      store.set(`${logOptionsStorageKey}.inlineDetailsNoScrolls`, newState);
    }

    setInlineNoScroll?.(newState);

    reportInteractionWrapper('logs_log_line_details_header_toggle_inline_no_scroll', {
      scroll: !newState,
    });
  }, [inlineNoScroll, logOptionsStorageKey, reportInteractionWrapper, setInlineNoScroll]);

  const toggleLogLine = useCallback(() => {
    if (logLineDisplayed) {
      onClickHideField?.(LOG_LINE_BODY_FIELD_NAME);
    } else {
      onClickShowField?.(LOG_LINE_BODY_FIELD_NAME);
    }
    reportInteractionWrapper('logs_log_line_details_header_show_logline_clicked');
  }, [logLineDisplayed, onClickHideField, onClickShowField, reportInteractionWrapper]);

  const clearSearch = useMemo(
    () => (
      <IconButton
        name="times"
        size="sm"
        onClick={() => {
          onSearch('');
          reportInteractionWrapper('logs_log_line_details_header_search_cleared');
          if (inputRef.current) {
            inputRef.current.value = '';
          }
        }}
        tooltip={t('logs.log-line-details.clear-search', 'Clear')}
      />
    ),
    [onSearch, reportInteractionWrapper]
  );

  const handleSearch = useCallback(
    (e: ChangeEvent<HTMLInputElement>) => {
      onSearch(e.target.value);
      if (!searchUsedRef.current) {
        reportInteractionWrapper('logs_log_line_details_header_search_used');
        searchUsedRef.current = true;
      }
    },
    [onSearch, reportInteractionWrapper]
  );

  const closeInlineDetails = useCallback(() => {
    toggleDetails(log);
  }, [log, toggleDetails]);

  const copyMenu = useMemo(
    () => (
      <Menu>
        <Menu.Item label={t('logs.log-line-details.copy-log-line', 'Copy log line message')} onClick={copyLogLine} />
        <Menu.Item
          label={t('logs.log-line-details.copy-log-line-json', 'Copy log contents as JSON')}
          onClick={copyLogLineAsJson}
        />
      </Menu>
    ),
    [copyLogLine, copyLogLineAsJson]
  );

  return (
    <div className={styles.header} ref={containerRef}>
      <Input
        onChange={handleSearch}
        placeholder={t('logs.log-line-details.search-placeholder', 'Search field names and values')}
        ref={inputRef}
        suffix={search !== '' ? clearSearch : undefined}
      />
      <div className={styles.icons}>
        {isAssistantAvailable && (
          <IconButton
            tooltip={t('logs.log-line-details.open-assistant', 'Explain log line in Assistant')}
            tooltipPlacement="top"
            size="md"
            name="ai-sparkle"
            onClick={() => openAssistantByLog?.(log)}
            tabIndex={0}
          />
        )}
        {focusLogLine && (
          <IconButton
            tooltip={t('logs.log-line-details.scroll-to-logline', 'Scroll to log line')}
            tooltipPlacement="top"
            size="md"
            name="arrows-v"
            onClick={scrollToLogLine}
            tabIndex={0}
          />
        )}
        {showLogLineToggle && (
          <IconButton
            tooltip={
              logLineDisplayed
                ? t('logs.log-line-details.hide-log-line', 'Hide log line')
                : t('logs.log-line-details.show-log-line', 'Show log line')
            }
            tooltipPlacement="top"
            size="md"
            name="eye"
            onClick={toggleLogLine}
            tabIndex={0}
            variant={logLineDisplayed ? 'primary' : undefined}
          />
        )}
        <Dropdown overlay={copyMenu} placement="auto-end">
          <IconButton
            tooltip={t('logs.log-line-details.copy-to-clipboard', 'Copy to clipboard')}
            tooltipPlacement="top"
            size="md"
            name="copy"
            tabIndex={0}
          />
        </Dropdown>
        {onPermalinkClick && log.rowId !== undefined && log.uid && (
          <IconButton
            tooltip={t('logs.log-line-details.copy-shortlink', 'Copy shortlink')}
            tooltipPlacement="top"
            size="md"
            name="share-alt"
            onClick={copyLinkToLogLine}
            tabIndex={0}
          />
        )}
        {pinned && onUnpinLine && (
          <IconButton
            size="md"
            name="gf-pin"
            onClick={togglePinning}
            tooltip={t('logs.log-line-details.unpin-line', 'Unpin log')}
            tooltipPlacement="top"
            tabIndex={0}
            variant="primary"
          />
        )}
        {!pinned && onPinLine && (
          <IconButton
            size="md"
            name="gf-pin"
            onClick={togglePinning}
            tooltip={t('logs.log-line-details.pin-line', 'Pin log')}
            tooltipPlacement="top"
            tabIndex={0}
          />
        )}
        {shouldlogSupportsContext && (
          <IconButton
            size="md"
            name="gf-show-context"
            onClick={showContext}
            tooltip={t('logs.log-line-details.show-context', 'Show context')}
            tooltipPlacement="top"
            tabIndex={0}
          />
        )}
        {setDetailsMode && (
          <>
            <div className={`${styles.divider} ${styles.dividerMargin}`} />
            {detailsMode === 'inline' && inlineNoScroll !== undefined && (
              <IconButton
                name={inlineNoScroll === true ? 'compress-arrows' : 'expand-arrows'}
                tooltip={
                  inlineNoScroll === true
                    ? t('logs.log-line-details.inline-with-scrolls', 'Switch to condensed view')
                    : t('logs.log-line-details.inline-no-scrolls', 'Switch to expanded view')
                }
                onClick={toggleDetailsScroll}
              />
            )}
            <IconButton
              name={detailsMode === 'inline' ? 'web-section' : 'gf-layout-simple'}
              tooltip={
                detailsMode === 'inline'
                  ? t('logs.log-line-details.sidebar-mode', 'Anchor to the right')
                  : t('logs.log-line-details.inline-mode', 'Display inline')
              }
              onClick={toggleDetailsMode}
            />
          </>
        )}
        <div className={styles.divider} />
        {detailsMode === 'sidebar' ? (
          <IconButton
            name="times"
            tooltip={t('logs.log-line-details.close-sidebar-details', 'Close log details sidebar')}
            variant="primary"
            onClick={closeDetails}
          />
        ) : (
          <IconButton
            name="times"
            tooltip={t('logs.log-line-details.close-inline-details', 'Close details for this log')}
            variant="primary"
            onClick={closeInlineDetails}
          />
        )}
      </div>
    </div>
  );
};

const getStyles = (theme: GrafanaTheme2, mode: LogLineDetailsMode, wrapLogMessage: boolean) => ({
  container: css({
    overflow: 'auto',
    height: '100%',
  }),
  scrollContainer: css({
    overflow: 'auto',
    height: '100%',
  }),
  header: css({
    alignItems: 'center',
    borderTopLeftRadius: mode === 'inline' ? theme.shape.radius.default : undefined,
    borderTopRightRadius: mode === 'inline' ? theme.shape.radius.default : undefined,
    background: theme.colors.background.canvas,
    display: 'flex',
    flexDirection: !wrapLogMessage && mode === 'inline' ? 'row-reverse' : 'row',
    gap: theme.spacing(0.75),
    zIndex: theme.zIndex.navbarFixed,
    height: theme.spacing(5.5),
    marginBottom: theme.spacing(1),
    padding: theme.spacing(0.5, 1),
  }),
  icons: css({
    display: 'flex',
    gap: theme.spacing(1),
    paddingLeft: theme.spacing(1),
    alignContent: 'center',
  }),
  copyLogButton: css({
    padding: 0,
    height: theme.spacing(4),
    width: theme.spacing(2.5),
    overflow: 'hidden',
    '&:hover': {
      backgroundColor: colorManipulator.alpha(theme.colors.text.primary, 0.12),
    },
  }),
  componentWrapper: css({
    padding: theme.spacing(0, 1, 1, 1),
  }),
  divider: css({
    width: 1,
    borderRight: `solid 1px ${theme.colors.border.medium}`,
    height: theme.spacing(2.25),
  }),
  dividerMargin: css({
    marginRight: theme.spacing(0.5),
  }),
});
